const res = $input.first().json;
const product = res.product ?? res;

if (!product?.id) {
  throw new Error(`Shopify product create failed — no product id. Response: ${JSON.stringify(res).slice(0, 500)}`);
}

if (product.status !== 'draft') {
  product.status = 'draft';
}

return [{ json: product }];

const productId = $('Create a product').first().json.id;
const imgbb = $('Upload to ImgBB').first().json?.data;
const imageSrc = imgbb?.image?.url || imgbb?.url || imgbb?.display_url || '';

const sourceItems = $input.all();
if (!sourceItems[0]?.binary?.data) {
  throw new Error(`No image binary from Download ImgBB for Shopify. URL: ${imageSrc}`);
}

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data', sourceItems);

function detectImageExt(buf) {
  if (!buf?.length) return null;
  if (buf[0] === 0x89 && buf[1] === 0x50) return 'png';
  if (buf[0] === 0xff && buf[1] === 0xd8) return 'jpg';
  if (buf[0] === 0x47 && buf[1] === 0x49) return 'gif';
  if (buf.length > 12 && buf.slice(0, 4).toString() === 'RIFF' && buf.slice(8, 12).toString() === 'WEBP') return 'webp';
  return null;
}

const ext = detectImageExt(buffer);
if (!ext) {
  throw new Error(`Downloaded file is not a valid image (${buffer.slice(0, 16).toString('hex')}) from ${imageSrc}`);
}

const binaryMeta = sourceItems[0].binary.data;
const filename = binaryMeta.fileName || (binaryMeta.fileExtension ? `product.${binaryMeta.fileExtension}` : `product.${ext}`);

return [{
  json: {
    product_id: productId,
    attachment: buffer.toString('base64'),
    filename,
    image_src: imageSrc,
    bytes: buffer.length,
  },
}];

const upload = $input.first().json;
const productId = $('Create a product').first().json.id;
const imgbb = $('Upload to ImgBB').first().json?.data;
const imgbbUrl = imgbb?.image?.url || imgbb?.url || imgbb?.display_url || '';
const src = upload?.image?.src ?? '';
const shopifyImageUrl = src || imgbbUrl;
const onShopifyCdn = src.includes('cdn.shopify.com') || src.includes('shopifycdn.com');

return [{
  json: {
    product_id: productId,
    shopify_image_url: shopifyImageUrl,
    shopify_image_ready: onShopifyCdn,
    image_source: onShopifyCdn ? 'shopify_cdn' : (src ? 'shopify_attachment' : 'imgbb_fallback'),
  },
}];

/**
 * Production scrape extractors for n8n Code nodes.
 * Pattern used by e-commerce automation teams:
 *   Tier 1: APIs + Schema.org JSON-LD (highest trust)
 *   Tier 2: OpenGraph / meta product tags
 *   Tier 3: Platform payloads (__NEXT_DATA__, Shopify embed, WooCommerce)
 *   Tier 4: HTML heuristics (images, price patterns)
 *   Tier 5: AI enrichment — gaps only (lowest cost, runs in separate node)
 *
 * Injected into Prepare page for scrape + Apply scraped data via patch script.
 */

/* global module */
const SCRAPE = {};

// ─── helpers ───────────────────────────────────────────────────────────────

SCRAPE.isDirectImageUrl = function isDirectImageUrl(url) {
  const u = String(url || '').trim().replace(/&amp;/g, '&');
  if (!u.startsWith('http')) return false;
  if (/\.html(?:\?|$|#)/i.test(u)) return false;
  if (/\.(jpe?g|png|webp|gif|avif)(\?|$|#)/i.test(u)) return true;
  if (/\/catalog\/product\//i.test(u)) return true;
  if (/\/wp-content\/uploads\//i.test(u)) return true;
  if (/\/media\/catalog\/product\//i.test(u)) return true;
  if (/\/cdn\/shop\//i.test(u)) return true;
  return false;
};

SCRAPE.absolutizeUrl = function absolutizeUrl(url, base) {
  const u = String(url || '').trim().replace(/&amp;/g, '&');
  if (!u) return '';
  if (u.startsWith('http')) return u;
  if (u.startsWith('//')) return `https:${u}`;
  try {
    return new URL(u, base).href;
  } catch {
    return u;
  }
};

SCRAPE.cleanText = function cleanText(t) {
  return String(t || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();
};

SCRAPE.meta = function meta(html, prop) {
  const re1 = new RegExp(`<meta[^>]+(?:property|name)=["']${prop}["'][^>]+content=["']([^"']+)["']`, 'i');
  const m1 = html.match(re1);
  if (m1) return m1[1];
  const re2 = new RegExp(`<meta[^>]+content=["']([^"']+)["'][^>]+(?:property|name)=["']${prop}["']`, 'i');
  const m2 = html.match(re2);
  return m2 ? m2[1] : '';
};

SCRAPE.extractJsonLd = function extractJsonLd(html) {
  const out = [];
  const re = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  while ((m = re.exec(html)) !== null) {
    try {
      out.push(JSON.parse(m[1]));
    } catch { /* skip */ }
  }
  return out;
};

SCRAPE.flattenJsonLd = function flattenJsonLd(blocks) {
  const items = [];
  for (const block of blocks) {
    if (!block) continue;
    if (Array.isArray(block)) items.push(...block);
    else if (block['@graph']) items.push(...(Array.isArray(block['@graph']) ? block['@graph'] : [block['@graph']]));
    else items.push(block);
  }
  return items;
};

SCRAPE.isProductType = function isProductType(t) {
  const type = String(t || '').toLowerCase();
  return type.includes('product');
};

SCRAPE.pickImageFromSchema = function pickImageFromSchema(image, baseUrl) {
  if (!image) return '';
  if (typeof image === 'string') return SCRAPE.absolutizeUrl(image, baseUrl);
  if (Array.isArray(image)) {
    for (const x of image) {
      const u = SCRAPE.pickImageFromSchema(x, baseUrl);
      if (u) return u;
    }
    return '';
  }
  if (typeof image === 'object') {
    return SCRAPE.absolutizeUrl(image.url || image.contentUrl || image['@id'] || '', baseUrl);
  }
  return '';
};

SCRAPE.parsePriceOffer = function parsePriceOffer(offers) {
  if (!offers) return { price: '', currency: '' };
  const list = Array.isArray(offers) ? offers : [offers];
  for (const o of list) {
    if (!o || typeof o !== 'object') continue;
    const price = o.price ?? o.lowPrice ?? o.highPrice ?? '';
    const currency = o.priceCurrency || '';
    if (price !== '' && price !== null) return { price: String(price), currency };
  }
  return { price: '', currency: '' };
};

// ─── Tier 1: JSON-LD Product ───────────────────────────────────────────────

SCRAPE.extractSchemaOrgProduct = function extractSchemaOrgProduct(html, baseUrl) {
  const blocks = SCRAPE.flattenJsonLd(SCRAPE.extractJsonLd(html));
  for (const item of blocks) {
    if (!item || typeof item !== 'object') continue;
    const types = item['@type'];
    const typeList = Array.isArray(types) ? types : [types];
    if (!typeList.some(SCRAPE.isProductType)) continue;

    const { price, currency } = SCRAPE.parsePriceOffer(item.offers);
    const brand = typeof item.brand === 'object' ? item.brand.name : item.brand;

    return {
      source: 'json_ld',
      confidence: 0.95,
      title: SCRAPE.cleanText(item.name || ''),
      description: SCRAPE.cleanText(item.description || ''),
      image_url: SCRAPE.pickImageFromSchema(item.image, baseUrl),
      competitor_price: price,
      competitor_currency: currency,
      vendor: SCRAPE.cleanText(brand || ''),
      product_category: SCRAPE.cleanText(item.category || ''),
      sku: String(item.sku || item.mpn || '').trim(),
    };
  }
  return null;
};

// ─── Tier 2: OpenGraph + meta product ──────────────────────────────────────

SCRAPE.extractOpenGraph = function extractOpenGraph(html, baseUrl) {
  const title = SCRAPE.meta(html, 'og:title') || SCRAPE.meta(html, 'twitter:title');
  const description = SCRAPE.meta(html, 'og:description') || SCRAPE.meta(html, 'description');
  const image = SCRAPE.meta(html, 'og:image') || SCRAPE.meta(html, 'twitter:image');
  const price = SCRAPE.meta(html, 'product:price:amount') || SCRAPE.meta(html, 'og:price:amount');
  const currency = SCRAPE.meta(html, 'product:price:currency') || SCRAPE.meta(html, 'og:price:currency');

  if (!title && !image && !description) return null;

  return {
    source: 'open_graph',
    confidence: 0.85,
    title: SCRAPE.cleanText(title),
    description: SCRAPE.cleanText(description),
    image_url: SCRAPE.absolutizeUrl(image, baseUrl),
    competitor_price: price ? String(price) : '',
    competitor_currency: currency || '',
    vendor: SCRAPE.cleanText(SCRAPE.meta(html, 'og:site_name')),
    product_category: '',
    sku: '',
  };
};

// ─── Tier 3: Platform payloads ─────────────────────────────────────────────

SCRAPE.extractHtmlTitle = function extractHtmlTitle(html) {
  const m = html.match(/<title[^>]*>([^<]+)<\/title>/i);
  if (!m) return '';
  let t = SCRAPE.cleanText(m[1]);
  t = t.replace(/\s*[|\-–]\s*Aarong.*$/i, '');
  t = t.replace(/\.html$/i, '');
  t = t.replace(/[-_]/g, ' ');
  if (/^[a-z0-9\s-]+\.html$/i.test(t) || t.length < 4) return '';
  return t.trim();
};

SCRAPE.extractNextData = function extractNextData(html, baseUrl) {
  const m = html.match(/<script id="__NEXT_DATA__"[^>]*>([\s\S]*?)<\/script>/i);
  if (!m) return null;
  try {
    const data = JSON.parse(m[1]);
    const blob = JSON.stringify(data);
    const titlePatterns = [
      /"name"\s*:\s*"([^"\\]{3,200})"/,
      /"title"\s*:\s*"([^"\\]{3,200})"/,
      /"product_name"\s*:\s*"([^"\\]{3,200})"/,
    ];
    let title = '';
    for (const re of titlePatterns) {
      const tm = blob.match(re);
      if (tm && !/\.html$/i.test(tm[1]) && tm[1].length > 3) {
        title = SCRAPE.cleanText(tm[1]);
        break;
      }
    }
    const images = [];
    for (const im of blob.matchAll(/https?:\\\/\\\/[^"\\]+?\.(?:jpe?g|png|webp|gif)(?:\?[^"\\]*)?/gi)) {
      images.push(im[0].replace(/\\\//g, '/'));
    }
    for (const im of blob.matchAll(/https?:\/\/[^"\\]+?\/(?:catalog|media)\/product\/[^"\\]+?\.(?:jpe?g|png|webp|gif)[^"\\]*/gi)) {
      images.push(im[0]);
    }
    const priceM = blob.match(/"price"\s*:\s*"?([0-9]+(?:\.[0-9]{1,2})?)"?/);
    if (!title && images.length === 0) return null;
    return {
      source: 'next_data',
      confidence: 0.8,
      title,
      description: '',
      image_url: images[0] || '',
      competitor_price: priceM ? priceM[1] : '',
      competitor_currency: '',
      vendor: '',
      product_category: '',
      sku: '',
      candidate_images: [...new Set(images)].slice(0, 10),
    };
  } catch {
    return null;
  }
};

SCRAPE.normalizeShopifyProduct = function normalizeShopifyProduct(json, baseUrl) {
  const p = json?.product;
  if (!p) return null;
  const v = p.variants?.[0] || {};
  const img = p.images?.[0]?.src || p.image?.src || '';
  return {
    source: 'shopify_json',
    confidence: 0.98,
    title: SCRAPE.cleanText(p.title || ''),
    description: SCRAPE.cleanText(p.body_html || ''),
    image_url: SCRAPE.absolutizeUrl(img, baseUrl),
    competitor_price: v.price ? String(v.price) : '',
    competitor_currency: '',
    vendor: SCRAPE.cleanText(p.vendor || ''),
    product_category: SCRAPE.cleanText(p.product_type || ''),
    sku: String(v.sku || '').trim(),
    sizes: (p.variants || []).map((x) => x.title).filter(Boolean),
    variants: (p.variants || []).map((x) => ({
      size: x.title,
      sku: x.sku,
      price: x.price,
    })),
  };
};

SCRAPE.shopifyJsonUrl = function shopifyJsonUrl(productUrl) {
  const u = String(productUrl || '').trim();
  if (!u) return '';
  if (u.includes('.json')) return u.split('?')[0];
  if (/\/products\/[^/?#]+/.test(u)) return `${u.replace(/\/$/, '').split('?')[0]}.json`;
  return '';
};

// ─── Tier 4: Images + price heuristics ─────────────────────────────────────

SCRAPE.extractProductImages = function extractProductImages(html, baseUrl) {
  const candidates = [];
  const seen = new Set();

  function add(url) {
    const u = SCRAPE.absolutizeUrl(url, baseUrl);
    if (!SCRAPE.isDirectImageUrl(u) || seen.has(u)) return;
    seen.add(u);
    candidates.push(u);
  }

  function rank(url) {
    if (/\/catalog\/product\//i.test(url) || /\/media\/catalog\/product\//i.test(url)) return 0;
    if (/\/cdn\/shop\//i.test(url)) return 1;
    if (/\/wp-content\/uploads\//i.test(url)) return 2;
    if (/\/catalog\/category\//i.test(url)) return 9;
    return 5;
  }

  for (const prop of ['og:image', 'twitter:image', 'og:image:url']) {
    add(SCRAPE.meta(html, prop));
  }

  for (const block of SCRAPE.flattenJsonLd(SCRAPE.extractJsonLd(html))) {
    if (!block || typeof block !== 'object') continue;
    add(SCRAPE.pickImageFromSchema(block.image, baseUrl));
  }

  const patterns = [
    /https?:\/\/[^"'\\s<>]+?\/catalog\/product\/[^"'\\s<>]+?\.(?:jpe?g|png|webp|gif)(?:\?[^"'\\s<>]*)?/gi,
    /https?:\/\/[^"'\\s<>]+?\/media\/catalog\/product\/[^"'\\s<>]+?\.(?:jpe?g|png|webp|gif)(?:\?[^"'\\s<>]*)?/gi,
    /https?:\/\/[^"'\\s<>]+?\/wp-content\/uploads\/[^"'\\s<>]+?\.(?:jpe?g|png|webp|gif)(?:\?[^"'\\s<>]*)?/gi,
    /https?:\/\/[^"'\\s<>]+?\/cdn\/shop\/[^"'\\s<>]+?\.(?:jpe?g|png|webp|gif)(?:\?[^"'\\s<>]*)?/gi,
  ];
  for (const re of patterns) {
    for (const m of html.matchAll(re)) add(m[0]);
  }

  const next = SCRAPE.extractNextData(html, baseUrl);
  if (next?.candidate_images) {
    for (const u of next.candidate_images) add(u);
  }

  for (const m of html.matchAll(/<img[^>]+src=["']([^"']+)["']/gi)) add(m[1]);
  for (const m of html.matchAll(/<img[^>]+data-src=["']([^"']+)["']/gi)) add(m[1]);

  candidates.sort((a, b) => rank(a) - rank(b));
  return candidates;
};

SCRAPE.extractPriceHeuristic = function extractPriceHeuristic(html) {
  const currencyPatterns = [
    { re: /(?:৳|BDT)\s*([0-9][0-9,]{2,}(?:\.[0-9]{1,2})?)/, currency: 'BDT' },
    { re: /([0-9][0-9,]{2,}(?:\.[0-9]{1,2})?)\s*(?:৳|BDT)/, currency: 'BDT' },
    { re: /(?:£|GBP)\s*([0-9][0-9,]*(?:\.[0-9]{1,2})?)/, currency: 'GBP' },
    { re: /(?:\$|USD)\s*([0-9][0-9,]*(?:\.[0-9]{1,2})?)/, currency: 'USD' },
  ];
  for (const { re, currency } of currencyPatterns) {
    const m = html.match(re);
    if (m) {
      const price = m[1].replace(/,/g, '');
      if (Number(price) >= 50) return { price, currency };
    }
  }
  return { price: '', currency: '' };
};

// ─── Merge tiers (production priority stack) ───────────────────────────────

SCRAPE.FIELD_ORDER = [
  'shopify_json',
  'json_ld',
  'open_graph',
  'next_data',
  'heuristic',
];

SCRAPE.mergeExtractions = function mergeExtractions(layers, baseUrl) {
  const byField = {};
  const sources = {};

  function set(field, value, source) {
    if (value === '' || value === null || value === undefined) return;
    if (byField[field] !== undefined && byField[field] !== '') return;
    byField[field] = value;
    sources[field] = source;
  }

  const sorted = [...layers].filter(Boolean).sort(
    (a, b) => SCRAPE.FIELD_ORDER.indexOf(a.source) - SCRAPE.FIELD_ORDER.indexOf(b.source)
  );

  for (const layer of sorted) {
    const src = layer.source;
    set('title', layer.title, src);
    set('description', layer.description, src);
    set('image_url', layer.image_url, src);
    set('competitor_price', layer.competitor_price, src);
    set('competitor_currency', layer.competitor_currency, src);
    set('vendor', layer.vendor, src);
    set('product_category', layer.product_category, src);
    set('sku', layer.sku, src);
    if (layer.sizes?.length) set('sizes', layer.sizes, src);
    if (layer.variants?.length) set('variants', layer.variants, src);
    if (layer.candidate_images?.length && !byField.candidate_images) {
      byField.candidate_images = layer.candidate_images;
      sources.candidate_images = src;
    }
  }

  return { ...byField, _sources: sources, _confidence: sorted[0]?.confidence || 0 };
};

SCRAPE.buildStructuredProduct = function buildStructuredProduct(html, baseUrl, shopifyLayer) {
  const candidateImages = SCRAPE.extractProductImages(html, baseUrl);
  const priceHint = SCRAPE.extractPriceHeuristic(html);
  const heuristic = {
    source: 'heuristic',
    confidence: 0.5,
    title: SCRAPE.extractHtmlTitle(html),
    description: '',
    image_url: candidateImages[0] || '',
    competitor_price: priceHint.price,
    competitor_currency: priceHint.currency,
    vendor: '',
    product_category: '',
    sku: '',
    candidate_images: candidateImages,
  };

  const structured = SCRAPE.mergeExtractions([
    shopifyLayer,
    SCRAPE.extractSchemaOrgProduct(html, baseUrl),
    SCRAPE.extractOpenGraph(html, baseUrl),
    SCRAPE.extractNextData(html, baseUrl),
    heuristic,
  ], baseUrl);

  if (!structured.candidate_images) structured.candidate_images = candidateImages.slice(0, 10);
  if (!structured.image_url && candidateImages[0]) {
    structured.image_url = candidateImages[0];
    structured._sources.image_url = 'candidate_images';
  }

  return structured;
};

SCRAPE.pickImageUrl = function pickImageUrl(scraped, row) {
  const ctx = row.scrape_context || {};
  const structured = ctx.structured || {};
  const candidates = [
    structured.image_url,
    scraped?.image_url,
    scraped?.product_image_url,
    ctx.og_image,
    ...(structured.candidate_images || ctx.candidate_images || []),
    row.validated_image_url,
    row['Product image URL'],
  ];
  for (const c of candidates) {
    if (SCRAPE.isDirectImageUrl(c)) return String(c).trim().replace(/&amp;/g, '&');
  }
  return '';
};

SCRAPE.mergeField = function mergeField(structured, ai, key, aiAlts = []) {
  const s = structured?.[key];
  if (s !== undefined && s !== null && String(s).trim() !== '') return s;
  for (const alt of aiAlts) {
    const v = ai?.[alt];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  const v = ai?.[key];
  return v !== undefined && v !== null ? v : '';
};


const row = $('Validate sheet row').first().json;
const http = $input.first().json;
const productUrl = row.source_product_url || row['Product URL'] || '';
let body = http.data ?? http.body ?? '';

if (typeof body !== 'string') {
  try { body = JSON.stringify(body); } catch { body = String(body); }
}

async function tryShopifyJson(url) {
  const jsonUrl = SCRAPE.shopifyJsonUrl(url);
  if (!jsonUrl) return null;
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: jsonUrl,
      json: true,
      timeout: 15000,
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
        Accept: 'application/json',
      },
    });
    return SCRAPE.normalizeShopifyProduct(res, url);
  } catch {
    return null;
  }
}

const shopifyLayer = await tryShopifyJson(productUrl);
const structured = SCRAPE.buildStructuredProduct(body, productUrl, shopifyLayer);
const candidateImages = structured.candidate_images || [];

const snippet = {
  product_url: productUrl,
  run_id: row._run_id,
  structured,
  extraction_sources: structured._sources || {},
  og_title: structured.title || SCRAPE.meta(body, 'og:title'),
  og_description: structured.description || SCRAPE.meta(body, 'og:description'),
  og_image: structured.image_url || SCRAPE.meta(body, 'og:image'),
  candidate_images: candidateImages.slice(0, 10),
  json_ld: SCRAPE.extractJsonLd(body).slice(0, 3),
  html_excerpt: body.replace(/<script[\s\S]*?<\/script>/gi, '').replace(/\s+/g, ' ').slice(0, 8000),
};

return [{ json: { ...row, scrape_context: snippet } }];

